INSERT INTO categories (slug, name) VALUES ('videokarty', 'Видеокарты'), ('processory', 'Процессоры'), ('materinskie-platy', 'Материнские платы') ON CONFLICT (slug) DO NOTHING;
INSERT INTO products (slug, name, description, price, category_id, image, available) SELECT v.slug, v.name, v.description, v.price, c.id, v.image, v.available FROM (VALUES ('geforce-rtx-4070', 'GeForce RTX 4070', 'Видеокарта', 89990, 'videokarty', '/images/nvidia-geforce-rtx-4070.svg', true), ('geforce-rtx-4060', 'GeForce RTX 4060', 'Видеокарта', 39990, 'videokarty', '', true), ('radeon-rx-7800-xt', 'Radeon RX 7800 XT', 'Видеокарта', 64990, 'videokarty', '', true), ('geforce-rtx-4090', 'GeForce RTX 4090', 'Видеокарта', 199990, 'videokarty', '', false), ('ryzen-5-7600x', 'Ryzen 5 7600X', 'Процессор', 27990, 'processory', '/images/amd-ryzen-5-7600x.svg', true), ('ryzen-7-7800x3d', 'Ryzen 7 7800X3D', 'Процессор', 49990, 'processory', '', true), ('core-i5-14600k', 'Core i5-14600K', 'Процессор', 35990, 'processory', '', true), ('core-i9-14900k', 'Core i9-14900K', 'Процессор', 69990, 'processory', '', true), ('msi-b650-gaming', 'MSI B650 Gaming', 'Материнская плата', 24990, 'materinskie-platy', '', true), ('asus-tuf-b650', 'ASUS TUF B650', 'Материнская плата', 28990, 'materinskie-platy', '', true), ('gigabyte-z790', 'Gigabyte Z790', 'Материнская плата', 32990, 'materinskie-platy', '', true), ('asrock-b550m', 'ASRock B550M', 'Материнская плата', 11990, 'materinskie-platy', '', true)) v(slug, name, description, price, category, image, available) JOIN categories c ON c.slug = v.category ON CONFLICT (slug) DO NOTHING;
INSERT INTO promos (title, text, product_id) SELECT 'Мощная графика', 'Игры в высоком разрешении', id FROM products WHERE slug = 'geforce-rtx-4070' ON CONFLICT DO NOTHING;
INSERT INTO promos (title, text, product_id) SELECT 'Процессор для игр', 'Быстрая сборка', id FROM products WHERE slug = 'ryzen-5-7600x' ON CONFLICT DO NOTHING;
